ProjectALife = ProjectALife or {}
ProjectALife.DialogueShards = ProjectALife.DialogueShards or {}
ProjectALife.DialogueShards["scenes_meet_1"] = {
{"fw_l23_cl_what_is_this","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,8|mood=fear|world=road|out=stay2",{1,"What the hell is this?! Officer, what is going on out here?",2,"Ma'am, slow down - anybody in your group bitten?",1,"No, no, nobody - we only just got out of the house",2,"Then keep it that way - stay off the road and keep your doors locked"}},
{"fw_l23_cl_my_mother","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|hour=16,5|mood=sad|world=window,building|out=stay2",{1,"They got my mother, she was on the porch and I was at the window...",2,"I'm sorry - where was this?",1,"Hollis Road, my brother is still in there with her - please, somebody has to go back...",2,"I can't leave this post tonight... I'll put the address on the list, and that's the best I can do"}},
{"fw_l23_cl_where_is_sheriff","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=m|day=0,10|mood=angry|out=part",{1,"Where's the sheriff? Somebody in charge has to know what this is",2,"The sheriff's been gone since Saturday, I've got a radio that says nothing",1,"So you don't know either",2,"No, sir, I don't, I wish I could tell you different"}},
{"fw_l23_cl_bitten_husband","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,12|hour=4,11|mood=sad|world=hot|out=stay2",{1,"My husband got scratched on the arm - it's shallow, he says he's fine",2,"How long ago?",1,"This morning, he's in the van, he's sweating, but it's hot out",2,"Ma'am, listen to me - keep your face away from his, if he stops answering you, you walk away"}},
{"fw_l23_cl_curfew","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|hour=16,5|mood=grim|out=stay2",{1,"Is there a curfew now? We saw a flyer on a pole",2,"Not from my office, that's the Army's paper, and they posted it before they left",1,"Left where?",2,"North, I'd stay in after dark whoever's name is on it"}},
{"fw_l23_cl_are_you_arresting","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=fear|world=door|out=stay2",{1,"Are you going to arrest us? We took food from the grocery on Main, the door was already open",2,"Nobody's arresting anybody for groceries today, I'm not even writing it down",1,"Thank God, I thought we were done for",2,"Just don't take more than you can carry out quiet - noise brings them"}},
{"fw_l23_cl_phones_dead","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,6|hour=20,5|mood=angry|out=part",{1,"I tried every payphone from here to the Dairy Bar - nothing but a busy tone",2,"Lines went down Friday night, my own phone at the station was dead by midnight",1,"Then how does anybody find out anything?",2,"They don't! That's what I keep running into"}},
{"fw_l23_cl_gun_question","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=grim|out=part",{1,"If I find my daddy's shotgun, am I allowed to carry it, or would you take it off me?",2,"I'd rather you knew how to handle it. Muzzle down and finger outside the guard",1,"I never shot at anything but a can before",2,"Then don't let having a gun talk you into a fight you could avoid"}},
{"fw_l23_cl_kids_hungry","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=sad|world=generator|out=walk",{1,"I keep thinking about families stuck without anything to eat",2,"If we meet any, we ask. No point saying we've got food before we check",1,"What if we haven't got enough?",2,"Then we say so. We don't send them somewhere on a guess"}},
{"fw_l23_cl_dont_trust_army","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,8|mood=angry|out=stay2",{1,"They told us on the TV to wait for the Army - I waited two days - nobody came",2,"I wouldn't count on them coming for you, ma'am, they've got their own priorities",1,"Meaning what?",2,"Meaning I saw convoys heading north and none of them stopped"}},
{"fw_l23_cl_post_office","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,6|mood=fear|world=road|out=part",{1,"Did you see what's at the post office? There's something in the lot, a lot of somethings",2,"I saw it, we're staying clear of that end of the street",1,"Should we go around?",2,"Go around it, and go slow, running makes them follow"}},
{"fw_l23_cl_i_know_you","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=warm|out=part",{1,"Deputy, you pulled my brother over last spring for the taillight",2,"The Chevy with the duct tape? Yeah, I remember that",1,"He's still driving it, or he was - I haven't heard from him since Friday",2,"Hold onto that, people turn up - I've seen it happen twice this week"}},
{"fw_l23_cl_looters","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=angry|out=stay2",{1,"Somebody's been through the hardware store and they were carrying more than they needed",2,"I know the type, we're not able to chase them down right now",1,"You're the law! Isn't that the entire point?",2,"The point today is keeping people breathing, the rest of it can wait on a judge"}},
{"fw_l23_cl_hold_here","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=calm|out=stay1",{1,"We were told to wait at the school - is that still the plan?",2,"As far as I know, yes, there's a unit set up there and a nurse",1,"Then we'll go on - thank you",2,"Stay together on the way, if somebody falls behind, don't go back for them alone"}},
{"fw_l23_cl_which_way_safe","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=fear|world=vehicle,cars,water,road|out=walk",{1,"Which way is clear? We came from Rosewood and the whole road was stopped cars",2,"I can't tell you a clear route. A familiar road isn't necessarily a safer one now",1,"We're on foot",2,"Then let's keep looking as we walk. I'm not promising a bridge or an open way through"}},
{"fw_l23_cl_dont_run","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=fear|world=road|out=stay2",{1,"They're slow - we could just outrun them, right?",2,"Some of them are slow, I watched one cover a parking lot faster than I ever could",1,"Oh, God",2,"So you walk, and you keep your head, your legs won't save you"}},
{"fw_l23_cl_dog","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=sad|out=part",{1,"My dog bit one of them - did that put her at risk?",2,"I honestly can't say, nobody has told me what a dog can catch",1,"She's been licking her paw all morning",2,"Keep her away from the little ones for a day or two... I'm sorry, that's the only advice I have"}},
{"fw_l23_cl_chicken_pox","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=sad|out=part",{1,"My girl asked if it's like the chicken pox, something that goes away...",2,"What did you tell her?",1,"That yes, it's a lot like that...",2,"I'd have told her the same, some days a lie is easier to carry than the truth"}},
{"fw_l23_cl_we_are_armed","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=calm|world=vehicle,road|out=stay1",{1,"We've got four guns between us - where do you want us?",2,"I want you home, honestly, but if you won't go, then stay out of our line",1,"We can watch the south road",2,"Fine, two of you at a time, and nobody shoots at a car before looking inside it"}},
{"fw_l23_cl_checkpoint_ahead","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=grim|world=vehicle|out=part",{1,"There's a roadblock up ahead - Army or yours?",2,"Not mine... I've got no roadblocks, only a patrol car with a flat",1,"They pointed rifles at us and told us to turn around",2,"Then do what they say, they don't ask twice"}},
{"fw_l23_cl_louisville","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,8|mood=grim|world=door|out=stay2",{1,"My sister is in Louisville - do you know anything about the city?",2,"I know the interstate's shut... I've heard the hospitals went first",1,"Went how?",2,"I'd rather not guess, ma'am, if she's smart she's somewhere high up with the door barred"}},
{"fw_l23_cl_stolen_truck","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=funny|world=vehicle,road|out=stay2",{1,"We borrowed a pickup from the lot at the feed store - the keys were in it",2,"Borrowed - right",1,"I left a note with my name on the windshield",2,"Then I've got nothing to write up. Drive careful"}},
{"fw_l23_cl_neighbor_locked","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=sad|out=stay1",{1,"My neighbor won't come out of his house and he's been calling for help since last night",2,"Calling from the inside?",1,"He's got a bite on him, I think, I could hear it in his voice",2,"Then he's gone, I'm sorry, we'll go by and do what needs doing - you stay here, don't watch..."}},
{"fw_l23_cl_water_running","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|hour=4,11|mood=calm|world=water,rain|out=stay2",{1,"Is the tap water safe? Mine ran brown this morning",2,"I wouldn't drink from it, plant at the river was one of the first things that stopped",1,"What else is there?",2,"Boil it twice if you have to use it, rain barrels are better"}},
{"fw_l23_cl_where_is_help","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,8|mood=angry|out=stay2",{1,"Is anyone coming? A real answer please, I won't get upset",2,"I haven't had a word from the state in days - as far as I know nobody is on the way",1,"You said that very flat!",2,"I've said it a dozen times today, ma'am, it doesn't get easier to say"}},
{"fw_l23_cl_siren","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,6|mood=fear|world=trees|out=stay2",{1,"Your siren set them off, they came out of the trees when you turned it on",2,"Yeah, shut it off already, force of habit",1,"A habit like that gets people killed",2,"You're right, nobody's going to hear it from me again"}},
{"fw_l23_cl_gas_station","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=calm|world=road|out=stay2",{1,"Is there any gas left? Our tank is nearly dry",2,"Mackey's on the highway still has a pump that works if you hand-crank it",1,"Is it guarded?",2,"Two men in lawn chairs with shotguns - tell them the deputy said it was fine"}},
{"fw_l23_cl_join_us","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=warm|out=walk",{1,"We're short on people who know how to fight - would you travel with us a while?",2,"I'm still sworn to this county, I can't just leave",1,"Just to the crossroads, we'd feel safer with a badge",2,"The crossroads I can do, after that you're on your own"}},
{"fw_l23_cl_church","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=warm|world=road|out=part",{1,"Everybody at our church is gone, I looked for the pastor and found his shoes in the road",2,"His shoes",1,"Just the shoes, set down neat like he'd stepped out of them",2,"I'm sorry, I don't have a better word for you than that"}},
{"fw_l23_cl_report_a_crime","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=funny|out=stay2",{1,"I want to report a man who shot at my truck - he did it twice",2,"Which direction was he shooting from?",1,"The overpass, the one on 31W",2,"Okay, I'll make a note, I don't have anybody to send but I'll make a note"}},
{"fw_l23_cl_badge_still_means","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=calm|out=stay2",{1,"Does the badge still mean anything now?",2,"It means I'm obliged to try, that's all it ever meant",1,"Then try to find my boy, he's fourteen, red jacket, about this tall",2,"Red jacket, I'll ask every person I meet - go to the school and wait there"}},
{"fw_l23_cl_dont_go_into_town","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=fear|world=door|out=stay2",{1,"We're heading into town to find my mother's pills",2,"Don't! Muldraugh is bad past the water tower",1,"She's got a heart condition, she's running out",2,"Then go to the pharmacy on the edge of town and nowhere farther - in and out, front door only"}},
{"fw_l23_cl_whose_side","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=angry|out=stay2",{1,"Are you the ones taking people's cars? A man said you took his!",2,"That wasn't us! There are folks wearing old uniforms who are not working for me",1,"How do I tell the difference?",2,"You can't, always - watch what they do, not what they wear"}},
{"fw_l23_cl_stay_in_pairs","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=calm|out=part",{1,"Anything we should do different when we're out walking?",2,"Go in pairs, no more than four, a big crowd makes noise and a lone person makes a meal",1,"And if one of us gets hurt?",2,"Then you stop and look, and you do not guess - look at the skin"}},
{"fw_l23_cl_listening_radio","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=grim|out=stay2",{1,"We got the AM station for a minute last night - it said to stay in our homes",2,"Mine said that too... then the signal went to hiss",1,"Is that good or bad?",2,"I decided not to think about it, you shouldn't either"}},
{"fw_l23_cl_take_my_son","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=sad|out=stay1",{1,"Please take my son with you, he's nine and he's quiet - he won't be any trouble...",2,"I can't do that, we're headed toward the worst of it",1,"Then where is he supposed to go?",2,"Where you go - keep him by you, that's the safest place he's got"}},
{"fw_l23_cl_old_man","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=warm|out=stay1",{1,"My father won't leave the house, he says he's lived there fifty years",2,"How old is he?",1,"Eighty-one, he keeps telling me to go on without him",2,"I'd be careful about arguing with him - leave a little water and a note, and come back for him when it's calm"}},
{"fw_l23_cl_arrest_dog_thief","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,14|mood=funny|out=part",{1,"Somebody stole my chickens - is that something we do anymore?",2,"Ma'am, I've seen the whole county on fire in the last week and you're asking about chickens",1,"They were good layers",2,"I'll keep an eye out for a man with feathers on him"}},
{"fw_l23_cl_hospital_rumor","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=fear|out=stay2",{1,"We heard the hospital took everyone in - is that true?",2,"The one in Louisville did, for the first day... I've heard nothing since then",1,"Should we try for it?",2,"I'd think very hard before I drove into a place where everyone was taken in"}},
{"fw_l23_cl_trust_me","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=warm|out=walk",{1,"How do I know I can trust you? You could be anyone with a badge",2,"You can't know it, you can walk a few feet behind me and see what I do",1,"That's fair",2,"Then we're going the same direction - fall in"}},
{"fw_l23_cl_drunk_deputy","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=funny|world=trees|out=part",{1,"A deputy back at the bridge smelled like a whole distillery",2,"Hale, I'll speak to him",1,"He told us everything was fine and then he waved at a tree",2,"Everything isn't fine, but I understand why he'd want to believe it"}},
{"fw_l23_cl_ambulance","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=sad|world=vehicle|out=part",{1,"An ambulance went by with the lights on and nobody inside but the driver - he was screaming...",2,"I heard it, I couldn't make myself follow",1,"Why not?",2,"Because I was scared too... I'll tell you that straight..."}},
{"fw_l23_cl_ration_plan","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=calm|world=door|out=stay2",{1,"Is there a plan for food? Anybody giving out portions?",2,"The VFW hall has a rice sack and a few cases of peaches - we're keeping a list",1,"Put us on it",2,"Names and head count - give them to the man at the door and he'll mark you"}},
{"fw_l23_cl_the_bridge","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=m|day=0,8|mood=fear|world=cars,water|out=part",{1,"The bridge at the river, is it open? We want to get across to my wife's family",2,"It's closed! The Army put up wire and they've got vehicles parked across it",1,"Can't we talk to them?",2,"Tell your wife's family to come to you, because you won't be getting there"}},
{"fw_l23_cl_bad_dream","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=sad|out=part",{1,"I keep thinking I'll wake up and it will be a regular Tuesday",2,"I've thought the same thing a few mornings, I don't wake up to it",1,"Do you ever stop?",2,"Not yet, but I get less surprised, if that counts"}},
{"fw_l23_cl_monsters","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,6|mood=fear|world=vehicle|out=stay2",{1,"What the hell is this?! Officer, please, there are monsters everywhere!",2,"Ma'am, I know... I've seen them",1,"It got my mother... and my brother, right in front of me!",2,"I'm sorry - come stand behind the cruiser while I figure out where we can send you"}},
{"fw_l23_cl_deputy_tired","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=sad|out=part",{1,"You look like you haven't sat down since Friday",2,"I sat down yesterday, for eleven minutes",1,"Can we do anything for you?",2,"Pour me a cup of something... I'll consider that a favor"}},
{"fw_l23_cl_stay_in_house","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=calm|world=door,road|out=stay1",{1,"Is it safe in our house or should we move?",2,"I can't judge a house without checking it. Think about a way out as well as keeping people out",1,"Would pushing a dresser against the front help?",2,"Maybe, but don't block your only escape. Work out which exits you can actually use"}},
{"fw_l23_cl_lost_kid","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=sad|out=stay2",{1,"Have you seen a little girl in a yellow raincoat? She's six",2,"How long since you saw her?",1,"An hour ago, she let go of my hand at the gas station",2,"Walk me through where you were, we'll start there..."}},
{"fw_l23_cl_call_from_inside","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=f|day=0,8|mood=fear|world=door,building|out=part",{1,"My husband called from the grocery, said the doors were locked from outside",2,"When was that?",1,"Ten minutes ago! Can you go?",2,"I'll check it - stay on the porch with the dog"}},
{"fw_l23_cl_old_cop_friend","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=warm|out=part",{1,"Is your name Hale? You used to work the night shift?",2,"That's me",1,"You gave me a ride home once when my car quit - I never thanked you",2,"Consider it accepted"}},
{"fw_l23_cl_thin_blue","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=funny|out=part",{1,"Officer, I want to report a robbery",2,"What was taken?",1,"My faith in humanity",2,"I'm afraid that's out of my jurisdiction"}},
{"fw_l23_cl_lock_your_door","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=calm|out=stay2",{1,"Anything else we ought to do?",2,"Lock your door and keep a flashlight by the bed - do not use the front steps at night",1,"Why not the front steps?",2,"They're the loudest part of any house"}},
{"fw_l23_cl_checkpoint_pass","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|mood=grim|out=stay2",{1,"We showed our papers to a soldier, he just shook his head",2,"He say anything?",1,"Nothing, he pointed back at the town",2,"Then I wouldn't push it"}},
{"fw_l23_cl_the_church_bell","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|hour=4,11|mood=fear|out=part",{1,"You hear that bell? It started this morning and hasn't stopped",2,"I heard it!",1,"Is somebody in there?",2,"I sent a man to see, he hasn't come back"}},
{"fw_l23_cl_badge_for_hire","meet",2,"r1=civilian,family,worker|r2=law,swat|x1=m|day=0,10|mood=angry|out=stay2",{1,"Are you going to protect us or just stand there?",2,"I'm going to do both, sir",1,"Then do one of them faster",2,"Point taken!"}},
{"fw_l23_cl_fence_line","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,12|mood=calm|out=stay1",{1,"We fenced off the lane with wire - is that all right with the county?",2,"The county's whatever I say it is today - it's fine",1,"Any advice?",2,"Hang cans on it, they'll tell you before you see anything"}},
{"fw_l23_cl_the_last_boy","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,8|hour=4,11|mood=sad|world=water|out=stay2",{1,"My son went to the creek this morning to fish - he hasn't come back",2,"Did he take the dog?",1,"He did",2,"Dogs sometimes find a way home - give it the night"}},
{"fw_l23_cl_found_baby","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,10|mood=warm|out=walk",{1,"We found a baby in a shopping cart behind the church - a note was pinned to the blanket",2,"What does it say?",1,"Please keep her safe, her name is Ruby",2,"Bring her with me, there's a woman at the aid station who will know what to do"}},
{"fw_l23_cl_thank_the_law","meet",2,"r1=civilian,family,worker|r2=law,swat|day=0,14|mood=warm|out=part",{1,"I just want to say thanks, you didn't have to stay",2,"Somebody had to",1,"Most of the others left",2,"I noticed, I'm not planning on it"}},
{"fw_l23_cm_what_the_hell","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=m|day=0,8|mood=fear|out=stay2",{1,"What the hell is this?! Please, you have to help us, there's something wrong with everybody!",2,"Sir, lower your voice - are you bitten or scratched?",1,"No, but it got my mother and my brother, they were right behind me!",2,"I'm sorry, we have a perimeter here and a job to do! Stay inside, let us work"}},
{"fw_l23_cm_appreciate_help","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=calm|world=door,road|out=stay2",{1,"We've got rifles, we can help you hold this street",2,"We appreciate it - stay inside your house and let us do the job",1,"You don't want more hands?",2,"I want fewer civilians in my line of fire - keep your family behind a locked door"}},
{"fw_l23_cm_tell_us_what_is_this","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,8|mood=angry|out=stay2",{1,"Somebody has to tell us what this is - is it a disease? A gas?",2,"I'm not cleared to say, ma'am, I can tell you what to do about it",1,"Then tell me!",2,"Stay away from the infected! And nobody bitten stays in your house, you hear?"}},
{"fw_l23_cm_quarantine_order","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=grim|world=water|out=stay2",{1,"The radio said the county is under quarantine - are we trapped here?",2,"There's a quarantine order in force, no unauthorized movement past the river",1,"What does that mean for people who live here?",2,"It means you shelter where you are, that is the safest thing for you right now"}},
{"fw_l23_cm_my_brother","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=sad|world=water|out=stay2",{1,"My brother was taken yesterday, down by the creek... I want to go look for him",2,"I can't allow that, the creek area isn't secure",1,"He might still be alive out there...",2,"Whatever is down there, it isn't something to walk into - I need you to stay put"}},
{"fw_l23_cm_watch_for_patrols","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=grim|world=road|out=stay2",{1,"Where's the safest direction to walk?",2,"Away from the highway... and if you see other troops, keep your hands visible",1,"Aren't they on your side?",2,"There are units out here with orders I don't know - be polite and get out of their way"}},
{"fw_l23_cm_hands_up","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=fear|out=stay2",{1,"Please don't shoot, we're not infected!",2,"Nobody's shooting - hands where I can see them, then turn around slowly",1,"Are you going to check us?",2,"Yes, it takes a minute - then you go back the way you came"}},
{"fw_l23_cm_where_is_evac","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,8|mood=angry|world=cars|out=stay2",{1,"Where's the evacuation? They said on the TV there'd be buses",2,"I haven't seen any buses, ma'am, I'm not going to lie to you",1,"So they lied to us!",2,"I think somebody believed it when they said it, that's not the same"}},
{"fw_l23_cm_be_ready_to_move","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|hour=16,5|mood=calm|world=door|out=stay2",{1,"What should we do if it gets worse?",2,"Keep a bag by the door with water and a first aid kit - and keep the lights off after dark",1,"Why the lights?",2,"They go toward light and noise - give them nothing to go toward"}},
{"fw_l23_cm_wounded_soldier","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,10|mood=sad|world=vehicle|out=walk",{1,"Your friend there is hurt, I could help, I used to be a nurse's aide",2,"Negative, ma'am - stay clear",1,"He's gray, he needs fluids...",2,"... Fine - walk with us to the truck, and stay three steps behind..."}},
{"fw_l23_cm_thank_you","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,14|mood=warm|out=stay2",{1,"God, am I glad to see you, we figured nobody was left",2,"We're not going anywhere, that's what we're here for",1,"Do you have family?",2,"I do, haven't been able to call them - go on inside, ma'am, and look after yours"}},
{"fw_l23_cm_we_need_our_truck","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=angry|out=part",{1,"You took our truck last night, we needed it",2,"It was requisitioned under the emergency order, a receipt was left on the seat",1,"A receipt! For my truck",2,"Take it up with the Army when this is over - I mean that sincerely"}},
{"fw_l23_cm_no_one_leaves","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|hour=16,5|mood=grim|world=cars|out=stay2",{1,"We were going to drive out tonight, get to my aunt in Bardstown",2,"You'll be turned around at the first checkpoint - or worse",1,"Worse how?",2,"There's a shoot-on-sight order for vehicles that run the line - I'd rather you didn't test it"}},
{"fw_l23_cm_dont_trust_trucks","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=fear|world=cars|out=stay2",{1,"Do you know the Guard trucks on 31W? Are those yours?",2,"We aren't in contact with them, treat them like anyone else",1,"Which means what?",2,"Which means don't wave and don't run toward them - let them pass"}},
{"fw_l23_cm_my_mother_still","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=sad|out=stay2",{1,"My mother is still in the house with them, I heard her last night...",2,"What did she say?",1,"She told me to go, so I went - please, I need to go back",2,"I can't let you, and I'm sorry for it, she told you to go because she wanted you alive"}},
{"fw_l23_cm_stay_inside","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|world=door|out=stay2",{1,"If I try going home, how do I know it's safe?",2,"I can't give you an all clear. Look before you commit, and be careful who you let in",1,"Not even for a soldier?",2,"A uniform doesn't tell you enough. Talk through the door first"}},
{"fw_l23_cm_cant_sleep","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|mood=sad|world=building|out=stay1",{1,"I haven't slept since Friday, I keep hearing it in the walls",2,"Hearing what?",1,"Scratching - footsteps, I don't know anymore...",2,"Take turns with someone, even an hour, the mind makes things up when it's tired..."}},
{"fw_l23_cm_headshots","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=grim|out=stay2",{1,"Is it true you have to shoot them in the head?",2,"Affirmative, center mass won't stop them",1,"I didn't know that... I shot one three times",2,"Then you've seen it get back up - save your ammunition for the head"}},
{"fw_l23_cm_leave_the_bitten","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,8|mood=grim|world=door|out=stay2",{1,"My neighbor's girl got bit - she's eleven - what do I do?",2,"How long?",1,"An hour, she's hot to the touch",2,"Get away from her, ma'am, put a closed door between you - this is not something you should have to carry"}},
{"fw_l23_cm_gas_mask","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,6|mood=fear|out=stay2",{1,"Why are you wearing masks? Is it in the air?",2,"Precaution, we don't know the vector yet",1,"Should we be wearing them?",2,"If you have a bandana, tie it on, it won't hurt and it might help"}},
{"fw_l23_cm_who_gives_orders","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,10|mood=angry|out=stay2",{1,"Who's in charge of you? I'd like a name",2,"A lieutenant! I couldn't give it to you",1,"That's not good enough!",2,"It's what I have! Go on home, ma'am!"}},
{"fw_l23_cm_airstrike_rumor","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,6|mood=fear|world=building|out=stay2",{1,"I heard you're going to bomb the whole county",2,"I've heard that too... nobody has told me it's true",1,"Is it?",2,"I wouldn't build a house on it, and I wouldn't ignore it - stay near a cellar"}},
{"fw_l23_cm_kid_salute","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|mood=warm|world=road|out=stay1",{1,"My boy wants to say hello, he wants to be a soldier",2,"Hey there, buddy - you stick close to your daddy, you hear?",1,"He says thank you",2,"Tell him he's welcome, tell him he's the bravest one on this street"}},
{"fw_l23_cm_clinic_open","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=calm|out=walk",{1,"Is there a medical station? We have a woman with a broken leg",2,"There's an aid tent behind the church - Corporal can walk you over",1,"Just us?",2,"Just you, the rest of your group waits here with me"}},
{"fw_l23_cm_dont_follow","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=grim|out=stay2",{1,"Can we follow you? We'd feel better",2,"No, we'll be moving through places you can't survive",1,"So we just sit?",2,"You sit, you eat what you have and you wait for the all-clear"}},
{"fw_l23_cm_are_you_scared","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|mood=funny|out=stay2",{1,"Are you scared? You look so calm",2,"Yes, I look calm because that's the training",1,"That's comforting, I guess",2,"It is for them, you can be scared as long as you stay quiet about it"}},
{"fw_l23_cm_boy_shot","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=fear|out=stay2",{1,"One of your men shot at us last night! Someone could have died!",2,"At what time?",1,"Eleven, we were at the barn",2,"A perimeter sentry, he was told to fire on anything moving, I will pass it up the chain"}},
{"fw_l23_cm_dry_orders","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|world=road|out=stay2",{1,"Is there anything we can bring you? Food, coffee?",2,"Don't promise food you might need yourself, thank you",1,"Anything at all",2,"A little room to think would be a good gift"}},
{"fw_l23_cm_how_long","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=sad|out=stay2",{1,"How long until this is over?",2,"I can't give you a number...",1,"A guess - days? Weeks?",2,"I don't want to tell you a guess and have you plan around it"}},
{"fw_l23_cm_widow","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,12|mood=sad|out=stay2",{1,"My husband was in the Guard, he got called up on Saturday - do you know the unit?",2,"What unit?",1,"The 138th, I think - Artillery...",2,"I don't know where that unit is now, ma'am. I hope he's well"}},
{"fw_l23_cm_stolen_medicine","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=grim|out=part",{1,"There's a man at the clinic with a rifle and a bag of pills - won't let anyone near",2,"How many with him?",1,"One... maybe two",2,"That one is ours to deal with - move away from the clinic and don't try to talk him down"}},
{"fw_l23_cm_old_neighbors","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|mood=warm|world=road|out=stay2",{1,"Our block's all older people, we made a rule that nobody goes out alone",2,"A good rule - who's the youngest among you?",1,"Me - I'm fifty-eight",2,"Then you're the one they'll listen to - keep that rule and keep your people off the street at night"}},
{"fw_l23_cm_curfew_start","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=m|day=0,8|hour=16,22|mood=grim|out=stay2",{1,"Is it true there's a curfew at dark?",2,"Yes, sir, anyone outside after dusk may be treated as a threat",1,"A threat to who?",2,"To everyone, including themselves - please be home by then"}},
{"fw_l23_cm_what_is_in_the_woods","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=fear|world=trees|out=stay2",{1,"There's a whole bunch of them in the pines behind our house - can't you do something?",2,"How many?",1,"I stopped counting at thirty",2,"That's for us to deal with - stay away from the tree line, and keep it quiet"}},
{"fw_l23_cm_wire_the_perimeter","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|world=vehicle,fence|out=walk",{1,"Do you need help stringing wire? I've done fencing all my life",2,"I do, actually, we're short on hands",1,"Then let me, I'd rather be useful than scared",2,"Come with us, then, stay behind the vehicle until I tell you"}},
{"fw_l23_cm_dead_eyes","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,8|mood=fear|out=stay1",{1,"They're not breathing... I put my ear right up against one and it wasn't breathing",2,"That's consistent with what we've seen",1,"How is that even possible?",2,"I don't know, ma'am, and I'm trained to say so"}},
{"fw_l23_cm_say_hi_to_mom","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|hour=16,5|mood=warm|out=stay1",{1,"If you ever get through to anyone outside, will you tell them we're alive?",2,"Give me the name and the town",1,"Ruth Calloway, Radcliff",2,"Ruth Calloway, Radcliff, I'll put it in the log tonight"}},
{"fw_l23_cm_obey_or_else","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=angry|out=stay2",{1,"You can't keep us here, this is America",2,"Today it's a quarantine zone, I didn't write the order",1,"Then who did?",2,"Someone with a bigger map than mine - I'm sorry"}},
{"fw_l23_cm_heroes","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,14|mood=warm|out=stay2",{1,"My kids think you're all heroes",2,"Tell them we're mostly tired",1,"I'll tell them you said so",2,"Tell 'em sitting still and quiet is the brave bit, honest"}},
{"fw_l23_cm_gunfire_overnight","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=fear|out=stay2",{1,"We heard shooting all night from the south - was that you?",2,"It was a team clearing the retail strip",1,"Did you get them all?",2,"We got what we could, more will come toward the noise, so keep your own noise down"}},
{"fw_l23_cm_monsters_everywhere","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,6|mood=fear|world=door,road|out=stay2",{1,"There are monsters everywhere! They're in the streets, in the yards, you have to help us!",2,"Ma'am- ma'am, are you hurt?",1,"It got my mother... then my brother, he was holding the door and it just took him",2,"I'm sorry for your loss, now go back inside and let us do our work"}},
{"fw_l23_cm_stay_inside_please","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=m|day=0,10|mood=calm|world=window,building|out=stay2",{1,"Soldier, we want to help, we can carry ammunition or watch a window",2,"Appreciate it, sir, but stay in your house and let us handle it",1,"What if they get into the house?",2,"Then you fight in the hallway where only one can reach you at a time"}},
{"fw_l23_cm_dont_look","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=fear|out=stay2",{1,"Is that a body under the tarp?",2,"Yes, please don't lift it!",1,"Someone I know could be under there",2,"Then you'll have to remember them the way they were"}},
{"fw_l23_cm_where_are_you_from","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,14|mood=warm|world=wind|out=part",{1,"Where are you from, son?",2,"Tulsa, ma'am - Oklahoma",1,"A long way to be, my cousin lives in Oklahoma",2,"Then you know about the wind, we don't get much wind here"}},
{"fw_l23_cm_you_look_scared","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,14|mood=funny|out=part",{1,"You can't be more than twenty",2,"Twenty-one in October, ma'am",1,"Does your mother know where you are?",2,"She does not, I'd like to keep it that way"}},
{"fw_l23_cm_watch_for_the_other_unit","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=grim|world=cars|out=part",{1,"Anything we should know about the trucks that came through last night?",2,"Stay clear of any unit that won't identify itself",1,"How would we know?",2,"They won't have our patches, and they won't answer your questions politely"}},
{"fw_l23_cm_close_the_windows","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|world=window,building|out=stay2",{1,"Should we board up the windows?",2,"Yes, use plywood or furniture - leave a slit so you can see out",1,"And if they break through?",2,"The upstairs bathroom has a lock - get everybody in there"}},
{"fw_l23_cm_wife_in_louisville","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=m|day=0,8|mood=sad|out=part",{1,"My wife was in Louisville, she went for the doctor Friday...",2,"I don't know what's happening there, sir",1,"Please, anything",2,"I can't tell you whether the bridges are open or where she went. I'm sorry, sir"}},
{"fw_l23_cm_no_visitors","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=grim|out=stay2",{1,"There's a man at our door every night, he knocks twice, then waits",2,"Do not open it",1,"He sounds like my brother",2,"Especially then, do not open it"}},
{"fw_l23_cm_ill_pray_for_you","meet",2,"r1=civilian,family,worker|r2=military,elite|x1=f|day=0,14|hour=16,5|mood=warm|out=part",{1,"I'll pray for you tonight, soldier",2,"Thank you, ma'am, I'd appreciate that",1,"What's your name?",2,"Private Alvarez"}},
{"fw_l23_cm_medical_check","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|mood=calm|out=stay2",{1,"One of my group has a fever - can you check her?",2,"Bring her to the vehicle, nobody else",1,"She's not bitten",2,"I believe you - it's procedure"}},
{"fw_l23_cm_trade_info","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|out=part",{1,"The north gate on the golf course is open, I thought you'd want to know",2,"Thank you - how many people use it?",1,"A handful at night - mostly families",2,"I'll mark it"}},
{"fw_l23_cm_wait_for_dawn","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|hour=16,5|mood=grim|out=stay2",{1,"It's getting dark - do you want us to go home now?",2,"Yes, be inside before the last light",1,"What about you?",2,"We stay out, that's what we're for"}},
{"fw_l23_cm_ground_rules","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,12|mood=calm|out=stay2",{1,"What are the rules, exactly? So we don't break any by accident",2,"No fires, no lights, no gunfire without a target",1,"What if there's a target?",2,"Then make it count, and don't miss"}},
{"fw_l23_cm_empty_house","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,10|hour=4,11|mood=sad|world=door|out=part",{1,"There's a house on the corner with the door wide open... no one inside",2,"We cleared it this morning",1,"What was in there?",2,"Nothing you'd want to see"}},
{"fw_l23_cm_dead_radio","meet",2,"r1=civilian,family,worker|r2=military,elite|day=0,8|mood=sad|out=part",{1,"You've got a radio - does it work?",2,"It works, there's just no one on the other end",1,"Do you try anyway?",2,"Every hour on the hour"}},
{"fw_l23_cr_what_is_happening","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=fear|out=part",{1,"What is happening to people? One minute my neighbor was fine and the next he was biting his wife!",2,"I've seen it eleven times since Friday... I don't have a name for it",1,"Is it a sickness?",2,"It acts like one, fever first, then it takes them all at once"}},
{"fw_l23_cr_check_my_arm","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=fear|world=fence|out=stay2",{1,"Can you look at my arm? I scraped it on a fence - I don't think it was them",2,"Come here, push the sleeve up",1,"Is it bad?",2,"It's a fence scrape, wire cut, clean edges, nothing in it, you're all right"}},
{"fw_l23_cr_my_mother_gone","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=sad|out=part",{1,"They got my mother... and my brother, I couldn't pull either of them out",2,"I'm sorry... I can hear how heavy that is",1,"What do I do with it?",2,"You carry it a day at a time, you don't have to decide anything today..."}},
{"fw_l23_cr_bitten_child","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|mood=sad|out=stay2",{1,"I once had a mother beg me to help her bitten daughter. Five years old",2,"What could you tell her?",1,"Nothing certain. She kept describing the child's calf, asking if being warm meant anything",2,"You don't forget a question you couldn't answer. I hope you didn't have to face her alone"}},
{"fw_l23_cr_water_supply","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|world=rain|out=stay2",{1,"Is the water from the tap safe?",2,"No, we stopped drinking it two days ago",1,"Then what do we drink?",2,"Rain if you can catch it, and boil whatever you find - don't trust a clear stream"}},
{"fw_l23_cr_fever_signs","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=fear|world=cold|out=stay2",{1,"How do I know if somebody is going to turn? Is there a sign?",2,"Fever that climbs fast, then shivering, then they go glassy",1,"And then?",2,"And then you need to be out of the room - don't wait to find out how long"}},
{"fw_l23_cr_ambulance_low","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|out=stay2",{1,"Somebody once asked me for insulin for their father. I didn't know what to say",2,"Were you able to find somebody qualified to help?",1,"I tried. Couldn't promise the medicine or tell them to change a prescribed dose",2,"I'd rather hear that than a promise you couldn't keep. Desperate people will plan around one"}},
{"fw_l23_cr_we_carry_wounded","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=warm|world=road|out=walk",{1,"Can you take my brother? He's got a broken ankle and can't walk",2,"We have a stretcher - which house?",1,"Two streets down, past the water tower",2,"Lead the way - stay where I can see you"}},
{"fw_l23_cr_ask_forgiveness","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,10|mood=sad|world=road|out=part",{1,"I left a man in the road, he was still moving, I couldn't help him",2,"Was he bitten?",1,"I think so... I didn't look",2,"Then you did the only thing you could, it doesn't feel like that now, I know"}},
{"fw_l23_cr_fire_everywhere","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,8|hour=16,5|mood=fear|out=part",{1,"The whole east side of town is burning - is anyone putting it out?",2,"We're trying, water pressure is nearly gone",1,"Is it going to reach us?",2,"Not tonight, and I'd rather not guess past tonight"}},
{"fw_l23_cr_how_many_saved","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=grim|out=stay2",{1,"How many people have you actually been able to save?",2,"I stopped counting on Monday",1,"That's no answer",2,"It's the only one I can give - sorry"}},
{"fw_l23_cr_church_shelter","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=warm|world=door,road|out=stay2",{1,"Is there any shelter nearby? We have two elders and a baby",2,"The brick church on the hill still has doors that lock - there's soup, there's a stove",1,"How do we get there?",2,"Follow the road, stay off the grass, bring the baby's blanket for the cold"}},
{"fw_l23_cr_pray_with_me","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,14|mood=warm|out=stay1",{1,"I don't know if I believe anymore - would you pray with me?",2,"I'd be glad to, I'm not sure I believe either, some mornings",1,"Then we're even",2,"Then we're in good company, bow your head"}},
{"fw_l23_cr_what_to_pack","meet",2,"r1=civilian,family,worker|r2=rescue|day=0,12|mood=calm|out=stay2",{1,"If we leave, what should we take?",2,"Water mostly, and bandages... oh, and something sweet for the kids",1,"What about guns?",2,"Whatever you've got, but don't let that be the only thing you pack"}},
}
